-- RANGE: родительская таблица и партиция на ноябрь.
CREATE TABLE orders (
    order_id bigint,
    order_date date NOT NULL
) PARTITION BY RANGE (order_date);

CREATE TABLE orders_2026_11 PARTITION OF orders
FOR VALUES FROM (DATE '2026-11-01') TO (DATE '2026-12-01');

-- LIST: родительская таблица, два города и остальные заказы.
CREATE TABLE orders_by_city (
    order_id bigint,
    city text NOT NULL
) PARTITION BY LIST (city);

CREATE TABLE orders_center PARTITION OF orders_by_city
FOR VALUES IN ('Москва', 'Тверь');

CREATE TABLE orders_other PARTITION OF orders_by_city DEFAULT;

-- HASH: родительская таблица и все четыре остатка.
CREATE TABLE orders_by_customer (
    order_id bigint,
    customer_id bigint NOT NULL
) PARTITION BY HASH (customer_id);

CREATE TABLE orders_hash_0 PARTITION OF orders_by_customer
FOR VALUES WITH (MODULUS 4, REMAINDER 0);

CREATE TABLE orders_hash_1 PARTITION OF orders_by_customer
FOR VALUES WITH (MODULUS 4, REMAINDER 1);

CREATE TABLE orders_hash_2 PARTITION OF orders_by_customer
FOR VALUES WITH (MODULUS 4, REMAINDER 2);

CREATE TABLE orders_hash_3 PARTITION OF orders_by_customer
FOR VALUES WITH (MODULUS 4, REMAINDER 3);

-- Синхронная реплика уже настроена.
BEGIN;
SET LOCAL synchronous_commit = 'remote_apply';
INSERT INTO orders (order_id, status) VALUES (314, 'created');
COMMIT;

-- Примеры для существующей таблицы orders с указанными столбцами.
-- B-tree: диапазон дат, order_date имеет тип date.
CREATE INDEX orders_date_btree ON orders USING BTREE (order_date);
-- WHERE order_date >= DATE '2026-11-01' AND order_date < DATE '2026-12-01'

-- Hash: точное совпадение.
CREATE INDEX orders_order_id_hash ON orders USING HASH (order_id);
-- WHERE order_id = 314

-- GIN: tags имеет тип text[].
CREATE INDEX orders_tags_idx ON orders USING GIN (tags);
-- WHERE tags @> ARRAY['gift']

-- BRIN: альтернатива для большой таблицы, упорядоченной примерно по дате.
CREATE INDEX orders_date_brin ON orders USING BRIN (order_date);

-- GiST: delivery_window имеет тип daterange.
CREATE INDEX orders_delivery_window_idx ON orders USING GIST (delivery_window);
-- WHERE delivery_window && daterange('2026-12-11', '2026-12-13', '[)')

-- SP-GiST: order_code имеет тип text.
CREATE INDEX orders_code_idx ON orders USING SPGIST (order_code);
-- WHERE order_code ^@ 'MSK-'

-- Выполни один раз в учебной БД, где схемы acid_demo ещё нет.
CREATE SCHEMA acid_demo;

CREATE TABLE acid_demo.inventory (
    product_id bigint PRIMARY KEY,
    stock integer NOT NULL CHECK (stock >= 0)
);

CREATE TABLE acid_demo.orders (
    order_id bigint PRIMARY KEY,
    product_id bigint NOT NULL REFERENCES acid_demo.inventory (product_id)
);

INSERT INTO acid_demo.inventory VALUES (42, 5), (99, 0);

-- Атомарность: товара 99 нет в наличии.
BEGIN;
INSERT INTO acid_demo.orders VALUES (314, 99);
UPDATE acid_demo.inventory
SET stock = stock - 1
WHERE product_id = 99 AND stock > 0;
-- UPDATE 0 — приложение проверяет число строк и отменяет заказ.
ROLLBACK;
SELECT * FROM acid_demo.orders WHERE order_id = 314; -- 0 строк

-- Проверка CHECK: выполни эту команду отдельно, вне BEGIN.
-- UPDATE acid_demo.inventory SET stock = -1 WHERE product_id = 42;
-- PostgreSQL отклонит изменение.

-- Изоляция: выполни команды в двух подключениях к той же БД.
-- Сеанс A:
BEGIN;
UPDATE acid_demo.inventory SET stock = 4 WHERE product_id = 42;

-- Сеанс B:
BEGIN ISOLATION LEVEL READ COMMITTED;
SELECT stock FROM acid_demo.inventory WHERE product_id = 42; -- 5

-- Сеанс A:
COMMIT;

-- Сеанс B:
SELECT stock FROM acid_demo.inventory WHERE product_id = 42; -- 4
COMMIT;

-- Долговечность при стандартных настройках PostgreSQL.
BEGIN;
INSERT INTO acid_demo.orders VALUES (315, 42);
COMMIT;
-- После восстановления от сбоя процесса следующий запрос вернёт заказ.
SELECT * FROM acid_demo.orders WHERE order_id = 315;

-- Выполни один раз в учебной БД. Затем открой сеансы A и B.
CREATE TABLE mvcc_demo_inventory (
    product_id integer PRIMARY KEY,
    stock integer NOT NULL
);
INSERT INTO mvcc_demo_inventory VALUES (42, 5);
-- Подготовка должна быть зафиксирована до начала опыта.

-- Сеанс A:
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT stock, xmin FROM mvcc_demo_inventory WHERE product_id = 42;

-- Сеанс B:
BEGIN;
UPDATE mvcc_demo_inventory SET stock = 4 WHERE product_id = 42;
COMMIT;

-- Сеанс A: по-прежнему 5 и прежний xmin.
SELECT stock, xmin FROM mvcc_demo_inventory WHERE product_id = 42;

-- Сеанс B: 4 и другой xmin.
SELECT stock, xmin FROM mvcc_demo_inventory WHERE product_id = 42;

-- Сеанс A:
COMMIT;

-- Сеанс B: вне транзакции, после окончания чтения в A.
VACUUM mvcc_demo_inventory;

practice.answer:
SELECT stock, xmin
FROM mvcc_demo_inventory
WHERE product_id = 42;

