-- Выполни в учебной базе, где схемы wal_demo ещё нет.
CREATE SCHEMA wal_demo;
CREATE TABLE wal_demo.orders (order_id bigint PRIMARY KEY);

SELECT pg_current_wal_insert_lsn() AS before_insert;

BEGIN;
INSERT INTO wal_demo.orders VALUES (316);
COMMIT;

SELECT pg_current_wal_insert_lsn() AS after_commit;
-- after_commit находится дальше по журналу.
-- WAL общий для экземпляра PostgreSQL: между замерами
-- журнал мог пополниться и записями других сеансов.

-- Выполни в учебной папке без файла orders_storage_demo.parquet.
COPY (
    SELECT * FROM (VALUES
        (314, DATE '2026-11-26', 900, 'ул. Лесная'),
        (315, DATE '2026-11-26', 600, 'ул. Садовая'),
        (316, DATE '2026-11-27', 400, 'ул. Полевая')
    ) AS orders(order_id, order_date, amount, delivery_address)
) TO 'orders_storage_demo.parquet' (FORMAT PARQUET);

SELECT SUM(amount) AS revenue
FROM read_parquet('orders_storage_demo.parquet')
WHERE order_date = DATE '2026-11-26';
-- Результат: 1500. Для расчёта нужны order_date и amount.

